import sympy
from sympy import Symbol, ZZ

x = Symbol('x')

def conditions(witness) -> list[bool]:
    # H_1: Let I = (x^2 + 1) be the principal ideal generated by the polynomial x^2 + 1 in R.
    # This implies that R is a ring containing the polynomial x^2 + 1.
    try:
        _ = witness.from_expr(x**2 + 1)
        h1 = True
    except Exception:
        h1 = False

    # ¬Q: The factor ring R/I is NOT isomorphic to the ring of Gaussian integers.
    # R/(x^2+1) is isomorphic to Gaussian integers if and only if R is isomorphic to ZZ[x].
    try:
        is_isomorphic = (witness.domain == ZZ) and (len(witness.gens) == 1)
        neg_q = not is_isomorphic
    except Exception:
        neg_q = True

    return [h1, neg_q]

CONDITION_LABELS = [
    "H_1: I is generated by x^2 + 1 in R",
    "¬Q: R/I is not isomorphic to Gaussian integers"
]

N_HYP = 1
NEG_Q_INDEX = 1